const ANTHROPIC_CC_API = "anthropic-cc-api";

// The host root exports the union, not its chat-specific interface.
type ProviderChatModelConfig = Extract<ProviderModelConfig, { type?: "chat" }>;
type StockModel = ProviderChatModelConfig & { compat?: Record<string, unknown> };

export const ANTHROPIC_CC_PREFERRED_MODEL_IDS = {
	opus: [
		"claude-opus-5-5",
		"claude-opus-5",
		"claude-opus-4-8",
		"claude-opus-4-7",
		"claude-opus-4-6",
		"claude-opus-4-5",
		"claude-opus-4-5-20251101",
		"claude-opus-4-1",
		"claude-opus-4-1-20250805",
		"claude-opus-4-0",
		"claude-opus-4-20250514",
	],
	sonnet: [
		"claude-sonnet-5-5",
		"claude-sonnet-5",
		"claude-sonnet-4-6",
		"claude-sonnet-4-5",
		"claude-sonnet-4-5-20250929",
