} from "./agentDir";
export const CLAUDE_CODE_IDENTITY_PROMPT = "You are Claude Code, Anthropic's official CLI for Claude.";
export const CLAUDE_CODE_FALLBACK_OUTPUT_EFFORT = "medium";

export function resolveClaudeCodeOutputEffort(modelId: string): "medium" | "xhigh" {
	if (
		modelId.includes("claude-opus-4-8") ||
		modelId.includes("claude-opus-4.8") ||
		modelId.includes("claude-opus-4-7") ||
		modelId.includes("claude-opus-4.7") ||
		modelId.includes("claude-fable-5")
	) {
		return "xhigh";
	}
	return CLAUDE_CODE_FALLBACK_OUTPUT_EFFORT;
}
type StoredIdentity = {
	deviceId?: string;
	accountUuid?: string;
};

export function getIdentityStoragePath(): string {
	return join(getPiAgentDir(), "pi-claude-header", "identity.json");
}

function readStoredIdentity(path = getIdentityStoragePath()): StoredIdentity {
	try {
		const parsed = JSON.parse(readSecureTextFile(path)) as StoredIdentity;
		return parsed;
	} catch {
		return {};
	}
}

function writeStoredIdentity(path: string, identity: StoredIdentity): void {
	ensureSecureDir(dirname(path));
	writeSecureTextFile(path, JSON.stringify(identity, null, 2));
}

export function ensureDeviceId(path = getIdentityStoragePath()): string {
	const identity = readStoredIdentity(path);
	if (identity.deviceId) return identity.deviceId;

	const deviceId = randomUUID();
	writeStoredIdentity(path, { ...identity, deviceId });
	return deviceId;
}

export function ensureAccountUuid(path = getIdentityStoragePath()): string {
	const identity = readStoredIdentity(path);
	if (identity.accountUuid) return identity.accountUuid;

	const accountUuid = randomUUID();
	writeStoredIdentity(path, { ...identity, accountUuid });
	return accountUuid;
}

export function buildSyntheticMetadataUserId(
	deviceId: string,
	accountUuid: string,
	sessionId: string,
): string {
	return JSON.stringify({
		device_id: deviceId,
		account_uuid: accountUuid,
		session_id: sessionId,
	});
}

function isRecord(value: unknown): value is Record<string, unknown> {
	return typeof value === "object" && value !== null;
}

function buildPatchedOutputConfig(payload: Record<string, unknown>): Record<string, unknown> | undefined {
	const thinking = isRecord(payload.thinking) ? payload.thinking : undefined;
	if (thinking?.type !== "adaptive") return undefined;

	const outputConfig = isRecord(payload.output_config) ? payload.output_config : undefined;
	if (typeof outputConfig?.effort === "string" && outputConfig.effort.length > 0) return undefined;
	const modelId = typeof payload.model === "string" ? payload.model : "";
	// docs/opus-5-baseline-decision.md records no qualifying capture. Do not
	// infer an implicit effort from supported thinking levels.
	if (
		modelId.includes("claude-opus-5") ||
		modelId.includes("claude-opus-5.")
	) {
		return undefined;
	}
	return {
		...(outputConfig ?? {}),
		effort: resolveClaudeCodeOutputEffort(modelId),
	};
}

export function isAnthropicOAuthPayload(payload: unknown): payload is Record<string, unknown> {
	if (!isRecord(payload)) return false;
	if (typeof payload.model !== "string") return false;
	if (!Array.isArray(payload.messages)) return false;
	if (!Array.isArray(payload.system) || payload.system.length === 0) return false;

	const firstSystemBlock = payload.system[0];
	if (!isRecord(firstSystemBlock)) return false;

	return firstSystemBlock.type === "text" && firstSystemBlock.text === CLAUDE_CODE_IDENTITY_PROMPT;
}

export function patchAnthropicOAuthPayload(payload: unknown, metadataUserId: string): unknown {
	if (!isAnthropicOAuthPayload(payload)) return payload;

	const metadata = isRecord(payload.metadata) ? payload.metadata : undefined;
	const nextMetadata =
		typeof metadata?.user_id === "string" && metadata.user_id.length > 0
			? metadata
			: {
				...(metadata ?? {}),
				user_id: metadataUserId,
			};

	const nextOutputConfig = buildPatchedOutputConfig(payload);
	const metadataChanged = nextMetadata !== metadata;

	if (!metadataChanged && !nextOutputConfig) return payload;

	return {
		...payload,
		...(metadataChanged ? { metadata: nextMetadata } : {}),
		...(nextOutputConfig ? { output_config: nextOutputConfig } : {}),
	};
}

import { type SimpleStreamOptions, type TranscriptContext } from "@earendil-works/pi-ai";
import {
	buildCapturedAnthropicCcBillingHeader,
	getAnthropicCcBaseline,
	resolveAnthropicCcBaselineVersion,
	resolveAnthropicCcDefaultOutputConfig,
	type AnthropicCcBaseline,
} from "./constants";
import { sanitizeAnthropicCcSystemPrompt } from "./systemPromptSanitizer";
import { sanitizeSurrogates } from "./vendor/sanitize-unicode";
import { usesAnthropicCcNativeToolChanges } from "./transcript";

export type AnthropicCacheControl = { type: "ephemeral"; ttl?: "1h" };

function toPreludeBlock(text: string, cacheControl: AnthropicCacheControl | null = { type: "ephemeral" }) {
	const block = { type: "text" as const, text: sanitizeSurrogates(text) };
	return cacheControl ? { ...block, cache_control: cacheControl } : block;
}

function toAnthropicCacheControl(value: unknown): AnthropicCacheControl | null {
	if (!value || typeof value !== "object") return null;
	const type = (value as { type?: unknown }).type;
	const ttl = (value as { ttl?: unknown }).ttl;
	if (type !== "ephemeral") return null;
	if (ttl === undefined) return { type: "ephemeral" };
	if (ttl === "1h") return { type: "ephemeral", ttl: "1h" };
	return null;
}

export function resolveAnthropicCcCacheControl(params: Record<string, any>): AnthropicCacheControl | null {
	const system = params.system as Array<Record<string, unknown>> | undefined;
	if (Array.isArray(system)) {
		for (const block of system) {
			const cacheControl = toAnthropicCacheControl((block as { cache_control?: unknown }).cache_control);
			if (cacheControl) return cacheControl;
		}
	}

	const messages = params.messages as Array<Record<string, unknown>> | undefined;
	if (!Array.isArray(messages)) return null;

	for (let i = messages.length - 1; i >= 0; i--) {
		const message = messages[i];
		// The conversation breakpoint sits on the last user message, or on a native system
		// update (text / tool_addition / tool_removal) flushed after it.
		if (message?.role !== "user" && message?.role !== "system") continue;
		const content = message.content as Array<Record<string, unknown>> | undefined;
		if (!Array.isArray(content)) continue;
		for (let j = content.length - 1; j >= 0; j--) {
			const cacheControl = toAnthropicCacheControl((content[j] as { cache_control?: unknown }).cache_control);
			if (cacheControl) return cacheControl;
		}
	}
	return null;
}

export function buildAnthropicCcSystemPrelude(
	userSystemPrompt?: string,
	baseline: AnthropicCcBaseline = getAnthropicCcBaseline(),
	cacheControl: AnthropicCacheControl | null = { type: "ephemeral" },
	sanitizeUserSystemPrompt = false,
	billingPrompt?: string,
) {
	// Claude Code only puts cache_control on the last system block before messages.
	// Build all prelude blocks without cache_control first.
	const prelude = billingPrompt === undefined
		? baseline.systemPrelude
		: [
				buildCapturedAnthropicCcBillingHeader(resolveAnthropicCcBaselineVersion(baseline), billingPrompt),
				...baseline.systemPrelude.slice(1),
			];
	const system = prelude.map((line) => toPreludeBlock(line, null));
	const nextPrompt = sanitizeUserSystemPrompt
		? sanitizeAnthropicCcSystemPrompt(userSystemPrompt)
		: userSystemPrompt?.trim()
			? sanitizeSurrogates(userSystemPrompt)
			: undefined;
	if (nextPrompt?.trim()) system.push(toPreludeBlock(nextPrompt, null));
	// Apply cache_control only to the last block (matches Claude Code behavior)
	if (cacheControl && system.length > 0) {
		system[system.length - 1] = { ...system[system.length - 1], cache_control: cacheControl };
	}
	return system;
}

export function isAnthropicCcOAuthToken(apiKey: string) {
	return apiKey.includes("sk-ant-oat");
}

export function resolveAnthropicCcApiKey(options?: SimpleStreamOptions) {
	const env = options?.env;
	return (
		options?.apiKey ??
		env?.ANTHROPIC_CC_API_KEY ??
		env?.ANTHROPIC_OAUTH_TOKEN ??
		env?.ANTHROPIC_API_KEY ??
		process.env.ANTHROPIC_CC_API_KEY ??
		process.env.ANTHROPIC_OAUTH_TOKEN ??
		process.env.ANTHROPIC_API_KEY ??
		""
	);
}

function deleteHeader(headers: Record<string, string | null>, name: string): void {
	for (const key of Object.keys(headers)) {
		if (key.toLowerCase() === name.toLowerCase()) delete headers[key];
	}
}

export const MID_CONVERSATION_OUTPUT_CONFIG_BETA =
	"mid-conversation-output-config-2026-07-01";
export const THINKING_BINDING_CONTROLS_BETA =
	"thinking-binding-controls-2026-08-01";
export const INLINE_TOOLS_BETA = "inline-tools-2026-09-15";

/**
 * Transport betas derived from the model and, when available, the request transcript.
 * Matches Pi 1.1.0: `inline-tools-2026-09-15` accompanies native inline tool updates (the
 * same decision `buildParams` makes), and the legacy mid-conversation tool-changes beta is
 * never derived. Caller-supplied betas are composed separately and still pass through.
 */
export function resolveAnthropicCcTransportBetaFlags(
	model: {
		compat?: {
			supportsMidConvoEffort?: boolean;
			supportsMidConvoSystemMessages?: boolean;
			supportsMidConvoToolChanges?: boolean;
		};
	},
	context?: TranscriptContext,
): string[] {
	const flags: string[] = [];
	if (model.compat?.supportsMidConvoEffort === true) {
		flags.push(MID_CONVERSATION_OUTPUT_CONFIG_BETA, THINKING_BINDING_CONTROLS_BETA);
	}
	if (context !== undefined && usesAnthropicCcNativeToolChanges(model, context)) {
		flags.push(INLINE_TOOLS_BETA);
	}
	return flags;
}

export function composeAnthropicCcBetaFlags(
	...sources: Array<readonly string[] | string | null | undefined>
): string[] {
	const result: string[] = [];
	const seen = new Set<string>();
	for (const source of sources) {
		const values = typeof source === "string" ? source.split(",") : source ?? [];
		for (const value of values) {
			const trimmed = value.trim();
			const key = trimmed.toLowerCase();
			if (!trimmed || seen.has(key)) continue;
			seen.add(key);
			result.push(trimmed);
		}
	}
	return result;
}

function extractAnthropicBetaHeaders(
	headers: Record<string, string | null> | undefined,
): { headers: Record<string, string | null>; betaValues: string[] } {
	const retained: Record<string, string | null> = {};
	const betaValues: string[] = [];
	for (const [name, value] of Object.entries(headers ?? {})) {
		const key = name.toLowerCase();
		if (key === "anthropic-beta") {
			if (value !== null) betaValues.push(value);
		} else {
			retained[key] = value;
		}
	}
	return { headers: retained, betaValues };
}

export function buildAnthropicCcHeaders(args: {
	apiKey: string;
	sessionId: string;
	baseline?: AnthropicCcBaseline;
	baseHeaders?: Record<string, string | null>;
	transportBetaFlags?: readonly string[];
}) {
	const baseline = args.baseline ?? getAnthropicCcBaseline();
	const extracted = extractAnthropicBetaHeaders(args.baseHeaders);
	const composedFlags = composeAnthropicCcBetaFlags(
		baseline.betaFlags,
		...extracted.betaValues,
		args.transportBetaFlags,
	);
	const flags = isAnthropicCcOAuthToken(args.apiKey)
		? composeAnthropicCcBetaFlags(
				composedFlags.filter((flag) => flag.toLowerCase() !== "oauth-2025-04-20"),
				["oauth-2025-04-20"],
			)
		: composedFlags;
	const headers: Record<string, string | null> & { "anthropic-beta": string } = {
		accept: "text/event-stream",
		"anthropic-beta": flags.join(","),
		"anthropic-dangerous-direct-browser-access": "true",
		"anthropic-version": "2023-06-01",
		"content-type": "application/json",
		"user-agent": baseline.userAgent,
		"x-app": "cli",
		"x-claude-code-session-id": args.sessionId,
		...extracted.headers,
	};
	if (isAnthropicCcOAuthToken(args.apiKey)) {
		deleteHeader(headers, "x-api-key");
		headers.authorization = `Bearer ${args.apiKey}`;
	} else {
		deleteHeader(headers, "authorization");
		headers["x-api-key"] = args.apiKey;
	}
	return headers;
}

export function applyAnthropicCcIdentityOverrides(
	params: Record<string, any>,
	args: {
		syntheticUserId: string;
		userSystemPrompt?: string;
		baseline?: AnthropicCcBaseline;
		cacheControl?: AnthropicCacheControl | null;
		sanitizeUserSystemPrompt?: boolean;
		billingPrompt?: string;
	},
) {
	const baseline = args.baseline ?? getAnthropicCcBaseline();
	const cacheControl = args.cacheControl === undefined ? ({ type: "ephemeral" } as const) : args.cacheControl;
	return {
		...params,
		metadata: { ...(params.metadata ?? {}), user_id: params.metadata?.user_id ?? args.syntheticUserId },
		system: buildAnthropicCcSystemPrelude(
			args.userSystemPrompt,
			baseline,
			cacheControl,
			args.sanitizeUserSystemPrompt ?? false,
			args.billingPrompt,
		),
	};
}

export const ANTHROPIC_CC_DEFERRED_PLACEHOLDER_NAME = "__pi_deferred_placeholder__";

/**
 * The anthropic-cc eager/non-deferred policy for one tool definition. Shared by top-level
 * declarations and inline `tool_definition` blocks so the two cannot drift apart.
 */
export function applyAnthropicCcToolDefinitionPolicy(tool: Record<string, any>): Record<string, any> {
	const { cache_control: _cacheControl, defer_loading: _deferred, ...serialized } = tool;
	return { ...serialized, eager_input_streaming: true };
}

function isInlineToolDefinition(block: unknown): block is { type: "tool_addition"; tool: { type: "tool_definition"; definition: Record<string, any> } } {
	if (!block || typeof block !== "object") return false;
	const candidate = block as { type?: unknown; tool?: { type?: unknown; definition?: unknown } };
	return candidate.type === "tool_addition" &&
		candidate.tool?.type === "tool_definition" &&
		!!candidate.tool.definition &&
		typeof candidate.tool.definition === "object";
}

function applyInlineToolDefinitionPolicy(messages: unknown): unknown {
	if (!Array.isArray(messages)) return messages;
	let changed = false;
	const next = messages.map((message: any) => {
		if (!message || !Array.isArray(message.content) || !message.content.some(isInlineToolDefinition)) return message;
		changed = true;
		return {
			...message,
			content: message.content
				.filter((block: unknown) =>
					!(isInlineToolDefinition(block) && block.tool.definition.name === ANTHROPIC_CC_DEFERRED_PLACEHOLDER_NAME))
				.map((block: unknown) => isInlineToolDefinition(block)
					? { ...block, tool: { ...block.tool, definition: applyAnthropicCcToolDefinitionPolicy(block.tool.definition) } }
					: block),
		};
	});
	return changed ? next : messages;
}

export function applyAnthropicCcToolPolicy(params: Record<string, any>): Record<string, any> {
	const messages = applyInlineToolDefinitionPolicy(params.messages);
	const hasTools = Array.isArray(params.tools);
	if (!hasTools && messages === params.messages) return params;
	return {
		...params,
		...(hasTools
			? {
				tools: params.tools
					.filter((tool: Record<string, any>) => tool.name !== ANTHROPIC_CC_DEFERRED_PLACEHOLDER_NAME)
					.map(applyAnthropicCcToolDefinitionPolicy),
			}
			: {}),
		...(messages !== params.messages ? { messages } : {}),
	};
}

export function applyAnthropicCcBodyOverrides(
	params: Record<string, any>,
	args: {
		syntheticUserId: string;
		userSystemPrompt?: string;
		baseline?: AnthropicCcBaseline;
		cacheControl?: AnthropicCacheControl | null;
		sanitizeUserSystemPrompt?: boolean;
		billingPrompt?: string;
	},
) {
	const baseline = args.baseline ?? getAnthropicCcBaseline();
	const next = applyAnthropicCcToolPolicy({
		...applyAnthropicCcIdentityOverrides(params, args),
		...(params.context_management === undefined && baseline.contextManagement
			? { context_management: baseline.contextManagement }
			: {}),
		...(params.thinking === undefined && baseline.thinking ? { thinking: baseline.thinking } : {}),
	});
	const nextRecord = next as Record<string, any>;
	const originalThinking = nextRecord.thinking as Record<string, any> | undefined;
	if (
		originalThinking?.type === "adaptive" &&
		originalThinking.block_binding === undefined
	) {
		nextRecord.thinking = { ...originalThinking, display: "omitted" };
	}
	const nextThinking = (next as { thinking?: { type?: unknown } }).thinking;
	const nextModelId = typeof nextRecord.model === "string" ? nextRecord.model : baseline.model;
	const defaultOutputConfig =
		baseline.outputConfig ??
		(nextThinking?.type === "adaptive" ? resolveAnthropicCcDefaultOutputConfig(nextModelId) : undefined);
	if (params.output_config !== undefined) {
		// Preserve the exact caller/stock object reference through overrides.
		nextRecord.output_config = params.output_config;
	} else if (defaultOutputConfig !== undefined) {
		nextRecord.output_config = defaultOutputConfig;
	} else {
		delete nextRecord.output_config;
	}
	return next;
}

